INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8b4d-7714-a444-3605890393d7'::uuid, '019f9df7-a2a2-7839-8287-1e75e9dd37f8'::uuid, 'A bag contains yellow and blue balls in the ratio 1:4. Five yellow balls are removed and 10 blue balls are added. The new ratio becomes 1:6. Find the original number of yellow balls.', '20', 'Let the original numbers be x and 4x. After the change, they become x - 5 and 4x + 10. Given (x - 5)/(4x + 10) = 1/6. So 6x - 30 = 4x + 10, hence 2x = 40 and x = 20.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.365Z'::timestamptz, '2026-08-15T07:36:12.365Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8b63-7902-9655-cbd7c2196711'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Each term in a sequence is obtained by subtracting the same number from the previous term. The sequence is 78, a, b, c, 42, ... Find a, b and c.', 'a = 69, b = 60, c = 51', 'There are 4 equal steps from 78 to 42, so the common difference is (42 - 78) ÷ 4 = -9. Therefore a = 69, b = 60 and c = 51.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.387Z'::timestamptz, '2026-08-15T07:36:12.387Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8b74-7d45-816f-ee81af7109da'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Write an expression in terms of n for the nth term of the sequence 78, 69, 60, 51, ...', '87 - 9n', 'The first term is 78 and the common difference is -9. So the nth term is 78 + (n - 1)(-9) = 87 - 9n.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.404Z'::timestamptz, '2026-08-15T07:36:12.404Z'::timestamptz) ON CONFLICT (id) DO NOTHING;